import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
import * as T from '../static/vendor/three-0.160.1.module.js';import Scene from '../static/pet-town-scene.js';import Town from '../static/pet-town-walk.js';
import {build,spec} from '../static/pet-snow-glass-lamp-proof-20261027/lamp.mjs';import {placeAndProbe,triangleRectangleDistance} from '../static/pet-snow-glass-lamp-proof-20261027/placement.mjs';import {fitView} from '../static/pet-scalloped-path-proof-20261027/framing.mjs';
const base=path.resolve(import.meta.dirname,'../static/pet-snow-glass-lamp-proof-20261027'),near=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,`${a} != ${b}`),box=m=>new T.Box3().setFromObject(m,true);
function topology(g){const p=g.attributes.position,n=g.attributes.normal,ix=g.index,edges=new Map(),v=i=>new T.Vector3().fromBufferAttribute(p,i),key=i=>v(i).toArray().map(x=>Math.round(x*1e7)).join(':');let volume=0,degenerate=0,negative=0;for(let i=0;i<(ix?ix.count:p.count);i+=3){const ids=[0,1,2].map(k=>ix?ix.getX(i+k):i+k),[a,b,c]=ids.map(v),cross=b.clone().sub(a).cross(c.clone().sub(a));if(cross.lengthSq()<1e-20){degenerate++;continue;}volume+=a.dot(b.clone().cross(c))/6;const normal=ids.map(k=>new T.Vector3().fromBufferAttribute(n,k)).reduce((a,b)=>a.add(b),new T.Vector3()).normalize();if(cross.clone().normalize().dot(normal)<=0)negative++;const ks=ids.map(key);for(let j=0;j<3;j++){const a=ks[j],b=ks[(j+1)%3],k=[a,b].sort().join('|'),r=edges.get(k)||{count:0,direction:0};r.count++;r.direction+=a<b?1:-1;edges.set(k,r);}}return{volume,degenerate,negative,badEdges:[...edges.values()].filter(x=>x.count!==2||x.direction!==0).length};}
const fixture=season=>{const world=Town.createWorld(),model=Scene.buildWorld(T,world,{},null,null,season),item=build(T);return{world,model,item,dispose(){item.dispose();model.dispose();}};};
test('37 actual parts include positive closed oriented roof, glass, tray, base and feet volumes with finite unit normals',()=>{const a=build(T);assert.equal(a.parts.length,37);for(const p of a.parts){const r=topology(p.mesh.geometry);assert.equal(r.badEdges,0,p.id);assert.equal(r.degenerate,0,p.id);assert.equal(r.negative,0,p.id);assert.ok(r.volume>0,p.id);}near(a.bounds.min[1],0);near(a.bounds.max[1],spec.height);assert.equal(a.inspect().invalidNormals,0);assert.equal(a.inspect().invalidPositions,0);a.dispose();});
test('all four glass panes have actual16mm-scaled solid thickness measured by entry/exit Mesh rays',()=>{const a=build(T),ray=new T.Raycaster();for(const pane of a.panes){pane.material.side=T.DoubleSide;const p=pane.position,front=pane.name.includes('front-back'),axis=front?'z':'x',sign=Math.sign(p[axis]),origin=new T.Vector3(p.x,p.y,p.z),dir=new T.Vector3();origin[axis]=sign*.50;dir[axis]=-sign;ray.set(origin,dir);const distances=[...new Set(ray.intersectObject(pane,false).map(h=>Math.round(h.distance*1e7)/1e7))].sort((a,b)=>a-b);assert.equal(distances.length,2);near(distances[1]-distances[0],spec.paneThickness);assert.ok(pane.material.transparent&&pane.material.opacity<1);assert.equal(pane.material.depthWrite,false);}assert.equal(a.panes.length,4);a.dispose();});
test('snow collector has a real recessed floor, four closed rails and an actual supported raised chamber',()=>{const a=build(T),ray=new T.Raycaster(),height=(mesh,x,z)=>{ray.set(new T.Vector3(x,2,z),new T.Vector3(0,-1,0));return ray.intersectObject(mesh,false)[0].point.y;};const floor=height(a.trayFloor,.37,0),rail=height(a.trayRails.find(x=>x.name==='snow-tray-side-0.415'),.415,0);near(floor,.3825);near(rail-floor,.0675);for(const foot of a.feet){near(box(foot).min.y,0);near(box(foot).max.y-box(a.base).min.y,.01);}near(box(a.base).max.y-box(a.stem).min.y,.03);near(box(a.stem).max.y-box(a.chamberBase).min.y,.0225);for(const post of a.posts)assert.ok(box(post).min.y<box(a.chamberBase).max.y);for(const pane of a.panes)near(box(a.chamberBase).max.y-box(pane).min.y,.0025);a.dispose();});
test('sloped roof has real underside depth, snow caps contact its top and four posts physically enter roof solids',()=>{const a=build(T),ray=new T.Raycaster();for(const roof of a.roof)roof.material.side=T.DoubleSide;for(const post of a.posts){ray.set(new T.Vector3(post.position.x,2,post.position.z),new T.Vector3(0,-1,0));const hits=ray.intersectObjects(a.roof,false).map(h=>h.point.y),bottom=Math.min(...hits),top=Math.max(...hits);assert.ok(bottom<box(post).max.y&&top>box(post).max.y);}for(const sign of[-1,1]){const roof=a.roof.find(x=>x.name.endsWith(sign<0?'left':'right')),cap=a.snow.find(x=>x.name==='snow-cap-'+(sign<0?'left':'right'));cap.material.side=T.DoubleSide;ray.set(new T.Vector3(sign*.25,2,0),new T.Vector3(0,-1,0));const roofYs=ray.intersectObject(roof,false).map(h=>h.point.y),snowYs=ray.intersectObject(cap,false).map(h=>h.point.y);near(Math.max(...roofYs)-Math.min(...roofYs),.06);near(Math.min(...snowYs),Math.max(...roofYs));near(Math.max(...snowYs)-Math.min(...snowYs),.045);}a.dispose();});
test('manual lamp switch changes emissive material only, rejects unknown states and never adds a light or moves geometry',()=>{const a=build(T),before=a.parts.map(p=>p.mesh.matrixWorld.toArray()),positions=a.parts.map(p=>Array.from(p.mesh.geometry.attributes.position.array));assert.equal(a.lit,true);a.setLit(false);assert.equal(a.inspect().emissiveIntensity,0);a.setLit(true);near(a.inspect().emissiveIntensity,.75);assert.throws(()=>a.setLit('yes'),/boolean/);assert.deepEqual(a.parts.map(p=>p.mesh.matrixWorld.toArray()),before);assert.deepEqual(a.parts.map(p=>Array.from(p.mesh.geometry.attributes.position.array)),positions);let lights=0;a.group.traverse(o=>{if(o.isLight)lights++;});assert.equal(lights,0);assert.equal(a.budget.lights,0);a.dispose();assert.throws(()=>a.setLit(true),/disposed/);});
test('twenty actual dry-land support rays and finite walkability preserve original world surfaces, occluders and scale',()=>{const f=fixture('winter'),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.supports.length,20);for(const row of p.supports)near(row.soleMinusFloor,0);assert.ok(p.finiteWalkability.samples>50);assert.equal(p.finiteWalkability.blocked,0);assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.ok(p.buildingProxyClearance.every(x=>!x.intersects));assert.equal(p.notRegisteredAsTownSurface,true);assert.equal(p.normalPlacement,false);near(p.characterScaleReference.frameWorldHeight,1.65);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);f.dispose();});
test('all actual road triangles clear the conservative footprint; an overlapping plaza and invalid point are rejected',()=>{const f=fixture('autumn'),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item),rect={minX:0,maxX:1,minZ:0,maxZ:1};assert.equal(p.roads.reduce((n,r)=>n+r.triangles,0),2022);assert.ok(p.minimumRoadGap>.58);near(triangleRectangleDistance([[2,0],[3,0],[2,1]],rect),1);near(triangleRectangleDistance([[-1,.4],[2,.4],[.5,.6]],rect),0);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width*.48,y:f.world.height*.52}),/road_clearance|footprint_blocked/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:NaN,y:10}),/anchor_invalid/);f.dispose();});
test('141 unchanged original cards retain conservative full-quad envelope clearance with physical and camera limits explicit',()=>{const f=fixture('summer'),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item),c=p.originalSpriteEnvelopeClearance;assert.equal(c.checkedCards,141);assert.ok(c.minimumGap>.92);assert.equal(c.physicalFixtureVolumes,false);assert.equal(c.allCameraProjectionOcclusionGuaranteed,false);assert.equal(f.model.scene.userData.originalArtRevision,'placement-originals1');assert.equal(f.model.scene.userData.originalArtRepresentation,'original-2d-art-in-3d-world');f.dispose();});
test('small resources dispose once and finite320/390 continuous-angle framing keeps real bounds without model resizing',()=>{const a=build(T),other=build(T);assert.equal(a.budget.triangles,688);assert.ok(a.budget.meshes<=40&&a.budget.geometries<=40&&a.budget.materials<=7);assert.equal(a.budget.textures,0);for(const width of[300,370])for(let yaw=-180;yaw<=180;yaw+=15)for(const pitch of[-80,12,88]){const f=fitView(T,a.bounds,{yaw,pitch,roll:yaw/3,distance:1},width/350);for(const n of Object.values(f.ndcBounds))assert.ok(Number.isFinite(n)&&Math.abs(n)<.87);}let count=0;const resources=Object.values(a.resources).flatMap(s=>[...s]);for(const o of resources)o.addEventListener('dispose',()=>count++);a.dispose();a.dispose();assert.equal(count,resources.length);assert.equal(a.group.children.length,0);assert.equal(other.disposed,false);other.dispose();});
test('manifest pins actual source/dependencies and raw renderer export; normal ownership/save and bitmap-generation counts stay zero',()=>{const m=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json')));assert.equal(m.model_id,spec.id);assert.equal(m.base_main_sha,'5538b774466a85cb6a5cedd81aed800c61e20300');for(const key of['normal_game_changes','new_raw_PNGs','new_original_PNG_designs','imagegen_calls'])assert.equal(m[key],0);assert.equal(m.new_mesh_candidate,1);const sha=b=>crypto.createHash('sha256').update(b).digest('hex');for(const r of m.inputs){const bytes=fs.readFileSync(path.resolve(import.meta.dirname,'..',r.path));assert.equal(bytes.length,r.bytes);assert.equal(sha(bytes),r.sha256);}for(const r of m.files){const bytes=fs.readFileSync(path.join(base,r.path));assert.equal(sha(bytes),r.sha256);}const v=fs.readFileSync(path.join(base,'viewer.mjs'),'utf8');assert.match(v,/toDataURL\('image\/png'\)/);assert.match(v,/fetch\('\/__capture\/lamp'/);assert.match(v,/visibilitychange/);assert.match(v,/pagehide/);assert.doesNotMatch(v,/localStorage|sessionStorage|saveGame|registerAsset/);});
